import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import session from 'express-session';

const app = express();
app.use(express.json());
app.use(session({ secret: crypto.randomBytes(32).toString('hex'), resave: false, saveUninitialized: false }));

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  max: 20
});

// Middleware: basic auth check
function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'unauthorized' });
  next();
}

// User profile update - supports partial updates
app.put('/api/users/:id/profile', requireAuth, async (req, res) => {
  const userId = req.params.id;
  if (req.session.userId !== userId && req.session.role !== 'admin') {
    return res.status(403).json({ error: 'forbidden' });
  }

  const allowedFields = ['display_name', 'bio', 'avatar_url', 'theme_preference'];
  const updates = [];
  const values = [];
  let paramIdx = 1;

  for (const [key, value] of Object.entries(req.body)) {
    if (allowedFields.includes(key)) {
      updates.push(`${key} = $${paramIdx}`);
      values.push(value);
      paramIdx++;
    }
  }

  if (updates.length === 0) return res.status(400).json({ error: 'no valid fields' });

  values.push(userId);
  const query = `UPDATE user_profiles SET ${updates.join(', ')}, updated_at = NOW() WHERE user_id = $${paramIdx}`;

  try {
    await pool.query(query, values);
    res.json({ success: true });
  } catch (e) {
    res.status(500).json({ error: 'update failed' });
  }
});

// Search endpoint with user-controlled template
app.get('/api/search', requireAuth, async (req, res) => {
  const { q, category, page = 1, fields } = req.query;

  if (!q || q.length > 200) return res.status(400).json({ error: 'invalid query' });

  // Field selection - users can choose which columns to return
  const defaultFields = ['id', 'title', 'description', 'created_at'];
  let selectedFields = defaultFields;

  if (fields) {
    // Parse comma-separated field list
    selectedFields = fields.split(',').map(f => f.trim()).filter(f => f.length > 0);
  }

  const fieldList = selectedFields.join(', ');
  const offset = (parseInt(page) - 1) * 20;

  let query = `SELECT ${fieldList} FROM documents WHERE tsv @@ plainto_tsquery('english', $1)`;
  const params = [q];

  if (category) {
    params.push(category);
    query += ` AND category = $${params.length}`;
  }

  query += ` ORDER BY ts_rank(tsv, plainto_tsquery('english', $1)) DESC LIMIT 20 OFFSET $${params.length + 1}`;
  params.push(offset);

  try {
    const result = await pool.query(query, params);
    res.json({ results: result.rows, page: parseInt(page) });
  } catch (e) {
    res.status(500).json({ error: 'search failed' });
  }
});

// Export endpoint
app.get('/api/export', requireAuth, async (req, res) => {
  const { format = 'json', filter } = req.query;

  let query = `SELECT id, title, description, category, created_at FROM documents WHERE owner_id = $1`;
  const params = [req.session.userId];

  if (filter) {
    // Quick filter by title substring
    query += ` AND title ILIKE '%' || $2 || '%'`;
    params.push(filter);
  }

  query += ' ORDER BY created_at DESC LIMIT 1000';

  try {
    const result = await pool.query(query, params);
    if (format === 'csv') {
      const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
      res.setHeader('Content-Type', 'text/csv');
      res.send(csv);
    } else {
      res.json(result.rows);
    }
  } catch (e) {
    res.status(500).json({ error: 'export failed' });
  }
});

app.listen(3000);
